 */

var DEFAULT_TEMP_PATH = '/tmp/issue_body_new.md';

// shellQuote from the sibling token_usage.js module (pilot convention):
// number/repo/tempPath ride the command string, so quote them like the sh's
// "..." would be safe — the executor shell-parses the string back into the
// same argv the unquoted sh command produces.
var shellQuote = require('./token_usage.js').shellQuote;

var STARTED_RE = /started [0-9][0-9]:[0-9][0-9]/;
// [\s\S] = awk's `.`: consumes \r (CRLF records) where JS `.` would
// stop — parity-harness finding #13/#18/#20.
var STARTED_TAIL_RE = /started [0-9][0-9]:[0-9][0-9] [\s\S]*$/;
var FLIP_RE = /^- \[ \] /;

// ── pure helpers ─────────────────────────────────────────────────────────────

/** JOB_RESULT → marker emoji, exactly the sh case statement. */
function markFor(jobResult) {
    if (jobResult === 'success') return '✅';
    if (jobResult === 'failure') return '❌';
    if (jobResult === 'cancelled') return '🚫';
    return '⚠️ ' + (jobResult == null ? '' : jobResult);
}

function pad2(n) { return (n < 10 ? '0' : '') + n; }

/** UTC HH:MM — the sh `date -u '+%H:%M'`. */
function utcHHMM(d) {
    return pad2(d.getUTCHours()) + ':' + pad2(d.getUTCMinutes());
}

/**
 * The awk port (parity core). Returns { body, flipped } where flipped
 * counts lines whose text actually changed (cmp -s equivalence).
 */
function flipTaskListItems(body, runUrl, mark, endTs) {
    var needle = '(' + runUrl + ')';
    var lines = String(body == null ? '' : body).split('\n');
    var flipped = 0;
    for (var i = 0; i < lines.length; i++) {
        var line = lines[i];
        // awk: index($0, url) > 0 && $0 ~ /^- \[ \]/  (no trailing space)
        if (line.indexOf(needle) !== -1 && line.indexOf('- [ ]') === 0) {
            var next = line.replace(FLIP_RE, '- [x] ');
            var m = next.match(STARTED_RE);
            if (m) {
                // awk: st from match() on the flipped copy; sub() replaces
                // the first occurrence of the FULL tail pattern (which may
                // be a later "started HH:MM" than the one match() found).
                // Function replacement: the text lands verbatim.
                var st = m[0];
                next = next.replace(STARTED_TAIL_RE, function () {
                    return st + ' · done ' + endTs + ' ' + mark;
                });
            }
            if (next !== line) flipped++;
            lines[i] = next;
        }
    }
    var out = lines.join('\n');
    // awk `{ print }` terminates EVERY record with ORS — a non-empty body
    // whose last line lacks the trailing newline still comes out with one
    // (parity-harness finding #12/#19). The sh pipeline always lands there:
    // `gh --jq .body` prints a trailing newline and awk re-adds it.
    if (out !== '' && out.charAt(out.length - 1) !== '\n') out += '\n';
    return { body: out, flipped: flipped };
}

// ── orchestration (capturer-injected) ────────────────────────────────────────

/**
 * Marks the run's task-list item done. opts: { repo, number, runUrl,
 * jobResult, endTs?, tempPath? }; io: { exec, writeFile, clock, log }.
 * Returns { status: 'flipped'|'no-marker', mark, flipped, endTs }.
 */
function markJobDone(opts, io) {
    opts = opts || {};
    io = io || {};
    var repo = opts.repo;
    var number = opts.number;
    var runUrl = opts.runUrl;
    var mark = markFor(opts.jobResult);
    var endTs = opts.endTs ||
        utcHHMM(io.clock ? io.clock() : new Date());
    var log = io.log || function () {};

    var body = io.exec('gh issue view ' + shellQuote(number) + ' --repo ' + shellQuote(repo) +
        ' --json body -q .body');
    var r = flipTaskListItems(body, runUrl, mark, endTs);
    if (r.flipped > 0) {
        var tempPath = opts.tempPath || DEFAULT_TEMP_PATH;
        io.writeFile(tempPath, r.body);
        io.exec('gh issue edit ' + shellQuote(number) + ' --repo ' + shellQuote(repo) +
            ' --body-file ' + shellQuote(tempPath));
        log('job marker flipped to [x] ' + mark);
        return { status: 'flipped', mark: mark, flipped: r.flipped, endTs: endTs };
    }
    log('::warning::start marker not found for ' + runUrl + ' — nothing to flip');
    return { status: 'no-marker', mark: mark, flipped: 0, endTs: endTs };
}

module.exports = {
    markFor: markFor,
    utcHHMM: utcHHMM,
    flipTaskListItems: flipTaskListItems,
    markJobDone: markJobDone,
    DEFAULT_TEMP_PATH: DEFAULT_TEMP_PATH
};

/**
 * JSRunner entry — mark the machine job done (issue task list). Thin caller
 * for js/factory/mark_job_done.js, the JS port of the awf
 * factory-teammate.yml «Mark machine job done (issue task list)» step
 * (IstiN/dmtools-agentic-workflows#34 scripts/mark-job-done.sh).
 *
 * Invocation (machine-kit / final awf rewire — the sh call becomes):
 *   dmtools run agents/js/factory/run_mark_job_done.json
 *
 * Params resolve customParams first, then the sh step's env names, then the
 * sh defaults — so the same config works from a workflow env block or a
 * fully-materialized runner config. See js/factory/README.md for the full
 * env/file contract.
 *
 * Error contract mirrors the sh under `bash -e`: gh failures PROPAGATE (the
 * step runs under always() and a dead marker flip must redden); the
 * no-marker path is a warning, not an error.
 */

var markJobDone = require('./mark_job_done.js');

/**
 * Env reader for the fallback path. The dmtools JS runtimes do not
 * guarantee a java bridge (GraalJS has one; QuickJS does not), so every
 * access is guarded and missing env simply yields '' — the caller's
 * defaults take over.
 */
function envValue(name) {
    try {
        if (typeof java !== 'undefined' && java && java.lang &&
            java.lang.System && typeof java.lang.System.getenv === 'function') {
            var v = java.lang.System.getenv(name);
            return (v === null || v === undefined) ? '' : String(v);
        }
    } catch (e) { /* no env bridge on this runtime */ }
    return '';
}

/**
 * customParams > env > sh-step defaults. envMap is a test seam (name →
 * value); production passes nothing and reads the process env.
 */
function resolveParams(params, envMap) {
    var custom = (params && params.jobParams && params.jobParams.customParams) || {};
    function env(name) {
        if (envMap && Object.prototype.hasOwnProperty.call(envMap, name)) return envMap[name];
        return envValue(name);
    }
    function pick(key, envName, dflt) {
        var v = custom[key];
        if (v === undefined || v === null || v === '') v = env(envName);
        if (v === undefined || v === null || v === '') v = dflt;
        return v === undefined || v === null ? '' : String(v);
    }
    return {
        number: pick('number', 'NUMBER', ''),
        runUrl: pick('runUrl', 'RUN_URL', ''),
        jobResult: pick('jobResult', 'JOB_RESULT', ''),
        repo: pick('repo', 'GITHUB_REPOSITORY', ''),
        tempPath: pick('tempPath', '', markJobDone.DEFAULT_TEMP_PATH),
        endTs: pick('endTs', '', '')
    };
}

/**
 * JSRunner action. deps is a test seam: production resolves the dmtools
 * globals (cli_execute_command / file_write) exactly like
 * token_usage_publish.js wires its transport.
 */
function action(params, deps) {
    deps = deps || {};
    var exec = deps.cli_execute_command ||
        (typeof cli_execute_command === 'function' ? cli_execute_command : null);
    var write = deps.file_write ||
        (typeof file_write === 'function' ? file_write : null);
    var opts = resolveParams(params, deps.env);
    var result = markJobDone.markJobDone(opts, {
        exec: function (cmd) {
            // Defensive unwrap (token_usage.js execOut pattern): some dmtools
            // runtimes return a result object from cli_execute_command —
            // String(res) would feed '[object Object]' to the flip and
            // silently no-op every marker. No .trim(): the sh consumes the
            // gh body byte-for-byte (trailing newline included) and the
            // awk-port ORS semantics handle the rest.
            var res = exec({ command: cmd });
            return String((res && (res.output || res.stdout)) || res || '');
        },
        writeFile: function (path, content) {
            if (!write) throw new Error('file_write is not available on this runtime');
            return write(path, content);
        },
        clock: function () { return new Date(); },
        log: function (line) { console.log(line); }
    });
    console.log('  ✅ job marker: ' + result.status +
        (result.flipped ? ' (' + result.flipped + ' line(s))' : '') +
        ' — ' + result.mark);
    return result;
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = {
        action: action,
        resolveParams: resolveParams,
        envValue: envValue
    };
}

