/** Body probe — decoded in-shell so JS never needs a base64 codec. */
function contentsBodyCommand(repo, path, branch) {
    return 'gh api repos/' + repo + '/contents/' + path + '?ref=' + branch +
        ' --jq .content | base64 -d';
