+
+  var COPILOT_USAGE = { provider: 'copilot', model: 'copilot/claude-sonnet-4.5', total_tokens: 6950 };
+
+  test('outputs/copilot_usage.json posts to the ADO ticket in ADO markdown shape', function () {
+    var mod = loadWith({
+      file_read: function (opts) {
