    }, { exec: stub.exec, read: function () { return COPILOT_RUN_OUTPUT; }, log: function () {} });
    assert.equal(r.status, 'published');
    assert.equal(r.key, 'issue-889');
    assert.equal(r.row.model, 'copilot/claude-sonnet-4.5');
