function bootstrapBranchCommand(repo, branch) {
    return 'gh api -X POST repos/' + repo + '/git/refs' +
        ' -f ref=refs/heads/' + branch +
        ' -f sha="$(gh api repos/' + repo +
        '/git/ref/heads/$(gh api repos/' + repo +
        ' --jq .default_branch) --jq .object.sha)" || true';
